import { LockOutlined, UserOutlined } from '@ant-design/icons';
import {
  FormattedMessage,
  Helmet,
  history,
  SelectLang,
  useIntl,
  useModel,
} from '@umijs/max';
import { Alert, App, Checkbox, Form, Space, theme } from 'antd';
import { createStyles } from 'antd-style';
import { motion } from 'framer-motion';
import React, { startTransition, useState } from 'react';
import { flushSync } from 'react-dom';
import { ClaudeButton, ClaudeInput, ClaudePassword } from '@/components/ui';
import { BrandPanel } from '@/components/ui/BrandPanel';
import { login } from '@/services/ant-design-pro/api';
import { motionTokens, prefersReducedMotion } from '@/styles/motion';
import { setAccessToken } from '@/utils/authToken';
import { resolvePostLoginRedirect } from '@/utils/postLoginRedirect';
import Settings from '../../../../config/defaultSettings';

const SUCCESS_ANIMATION_DELAY_MS = 350;

const useStyles = createStyles(({ token }: { token: any }) => ({
  formTitle: {
    fontSize: token.fontSizeHeading1,
    fontWeight: token.fontWeightSemibold,
    color: token.colorText,
    lineHeight: 1.3,
    marginBottom: 6,
    letterSpacing: '-0.01em',
  },

  formSubtitle: {
    fontSize: token.fontSize,
    fontWeight: token.fontWeightRegular,
    color: token.colorTextSecondary,
    lineHeight: 1.6,
    marginBottom: 20,
  },

  errorAlert: {
    marginBottom: 20,
  },

  autoLoginRow: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 20,
  },

  forgotLink: {
    fontSize: 13,
    color: token.colorTextSecondary,
    cursor: 'pointer',
    transition: 'color 0.15s ease',
    '&:hover': {
      color: token.colorPrimary,
    },
  },

  registerEntry: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 24,
    fontSize: token.fontSize,
    color: token.colorTextSecondary,
    cursor: 'pointer',
    transition: 'color 0.15s ease',
    '&:hover': {
      color: token.colorPrimary,
    },
  },
}));

const Lang = () => (
  <div
    style={{
      position: 'fixed',
      top: 20,
      right: 24,
      zIndex: 100,
    }}
  >
    <SelectLang />
  </div>
);

const LoginMessage: React.FC<{ content: string }> = ({ content }) => (
  <Alert message={content} type="error" showIcon />
);

const Login: React.FC = () => {
  const [userLoginState, setUserLoginState] = useState<API.LoginResult>({});
  const [submitting, setSubmitting] = useState(false);
  const { initialState, setInitialState } = useModel('@@initialState');
  const { styles } = useStyles();
  const { message } = App.useApp();
  const intl = useIntl();
  const { token } = theme.useToken();

  const fetchUserInfo = async () => {
    const userInfo = await initialState?.fetchUserInfo?.();
    if (userInfo) {
      flushSync(() => {
        setInitialState((s) => ({
          ...s,
          currentUser: userInfo,
        }));
      });
    }
    return userInfo;
  };

  const handleSubmit = async (values: API.LoginParams) => {
    try {
      setSubmitting(true);
      const msg = await login({ ...values, type: 'account' });
      if (msg.status === 'ok' && msg.token) {
        setAccessToken(msg.token);
        const defaultLoginSuccessMessage = intl.formatMessage({
          id: 'pages.login.success',
          defaultMessage: '登录成功',
        });
        message.success(defaultLoginSuccessMessage);
        const userInfo = await fetchUserInfo();
        const urlParams = new URL(window.location.href).searchParams;
        const nextPath = resolvePostLoginRedirect(
          urlParams.get('redirect'),
          userInfo,
        );
        await new Promise((resolve) => {
          window.setTimeout(resolve, SUCCESS_ANIMATION_DELAY_MS);
        });
        startTransition(() => {
          history.push(nextPath);
        });
        return;
      }

      const nextState = {
        ...msg,
        status: msg.status || 'error',
      };
      setUserLoginState(nextState);
      if (nextState.errorMessage) {
        message.error(nextState.errorMessage);
      }
    } catch (error: unknown) {
      const err = error as {
        response?: { data?: { detail?: string } };
        info?: { errorMessage?: string };
      };
      const backendMessage =
        err?.response?.data?.detail || err?.info?.errorMessage;
      const defaultLoginFailureMessage = intl.formatMessage({
        id: 'pages.login.failure',
        defaultMessage: '登录失败，请重试',
      });
      setUserLoginState({
        status: 'error',
        errorMessage: backendMessage || defaultLoginFailureMessage,
      });
      message.error(backendMessage || defaultLoginFailureMessage);
    } finally {
      setSubmitting(false);
    }
  };

  const { status, errorMessage } = userLoginState;
  const reducedMotion = prefersReducedMotion();

  const MotionDiv = reducedMotion ? 'div' : motion.div;

  const titleAnim = reducedMotion
    ? {}
    : {
        initial: { opacity: 0, y: 16 },
        animate: { opacity: 1, y: 0 },
        transition: {
          duration: motionTokens.duration.normal,
          ease: motionTokens.easing.enter,
        },
      };

  const subtitleAnim = reducedMotion
    ? {}
    : {
        initial: { opacity: 0, y: 16 },
        animate: { opacity: 1, y: 0 },
        transition: {
          duration: motionTokens.duration.normal,
          delay: 0.2,
          ease: motionTokens.easing.enter,
        },
      };

  return (
    <>
      <Helmet>
        <title>
          {intl.formatMessage({
            id: 'menu.login',
            defaultMessage: '登录',
          })}
          {Settings.title && ` - ${Settings.title}`}
        </title>
      </Helmet>
      <Lang />
      <div className="auth-root" data-testid="login-page-shell">
        <BrandPanel />

        {/* Right panel: form area */}
        <div className="auth-right">
          <div className="auth-card" data-testid="login-form-card">
            <MotionDiv {...titleAnim}>
              <div className={styles.formTitle}>欢迎回来</div>
            </MotionDiv>
            <MotionDiv {...subtitleAnim}>
              <div className={styles.formSubtitle}>
                <FormattedMessage
                  id="pages.login.subtitle"
                  defaultMessage="登录以继续使用"
                />
              </div>
            </MotionDiv>

            {status === 'error' && (
              <div className={styles.errorAlert}>
                <LoginMessage
                  content={
                    errorMessage || '用户名或密码错误（管理员：admin / 123456）'
                  }
                />
              </div>
            )}

            <Form
              layout="vertical"
              requiredMark="optional"
              onFinish={async (values) => {
                await handleSubmit(values as API.LoginParams);
              }}
            >
              <Form.Item
                name="username"
                rules={[
                  {
                    required: true,
                    message: (
                      <FormattedMessage
                        id="pages.login.username.required"
                        defaultMessage="请输入用户名"
                      />
                    ),
                  },
                ]}
              >
                <ClaudeInput
                  id="username"
                  size="large"
                  prefix={
                    <UserOutlined style={{ color: token.colorTextTertiary }} />
                  }
                  placeholder={intl.formatMessage({
                    id: 'pages.login.username.placeholder',
                    defaultMessage: '用户名：admin 或普通用户',
                  })}
                  style={{ height: 40 }}
                />
              </Form.Item>

              <Form.Item
                name="password"
                rules={[
                  {
                    required: true,
                    message: (
                      <FormattedMessage
                        id="pages.login.password.required"
                        defaultMessage="请输入密码"
                      />
                    ),
                  },
                ]}
              >
                <ClaudePassword
                  id="password"
                  size="large"
                  prefix={
                    <LockOutlined style={{ color: token.colorTextTertiary }} />
                  }
                  placeholder={intl.formatMessage({
                    id: 'pages.login.password.placeholder',
                    defaultMessage: '密码：管理员为 123456',
                  })}
                  style={{ height: 40 }}
                />
              </Form.Item>

              <div className={styles.autoLoginRow}>
                <Form.Item name="autoLogin" valuePropName="checked" noStyle>
                  <Checkbox>
                    <span
                      style={{
                        fontSize: 13,
                        color: token.colorTextSecondary,
                      }}
                    >
                      <FormattedMessage
                        id="pages.login.remember"
                        defaultMessage="记住登录"
                      />
                    </span>
                  </Checkbox>
                </Form.Item>

                <span
                  className={styles.forgotLink}
                  data-testid="forgot-password-link"
                  onClick={() => {
                    message.info(
                      intl.formatMessage({
                        id: 'pages.login.forgot',
                        defaultMessage: '请联系管理员重置密码',
                      }),
                    );
                  }}
                >
                  <FormattedMessage
                    id="pages.login.forgotPassword"
                    defaultMessage="忘记密码？"
                  />
                </span>
              </div>

              <Form.Item style={{ marginBottom: 0 }}>
                <ClaudeButton
                  variant="terracotta"
                  htmlType="submit"
                  size="large"
                  block
                  loading={submitting}
                  style={{ height: 40 }}
                >
                  <FormattedMessage
                    id="pages.login.submit"
                    defaultMessage="登录"
                  />
                </ClaudeButton>
              </Form.Item>
            </Form>

            <div
              className={styles.registerEntry}
              data-testid="register-account-link"
              onClick={() => {
                startTransition(() => {
                  history.push('/user/register');
                });
              }}
            >
              <FormattedMessage
                id="pages.login.noAccount"
                defaultMessage="还没有账户？"
              />
              <Space size={4} />
              <span style={{ color: token.colorPrimary, fontWeight: 500 }}>
                <FormattedMessage
                  id="pages.login.register"
                  defaultMessage="立即注册"
                />
              </span>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default Login;

