              <Card>
                <Statistic title="已完成评估人数" value={data?.total_assessments ?? 0} />
              </Card>
            </Col>
            <Col xs={24} sm={8}>
              <Card>
                <Statistic title="覆盖维度数" value={radarData.length} />
